size(200);
defaultpen(linewidth(0.6));
pair A = IP((0,0), dir(150)*dir(90)), B = IP((0,0), dir(-30)*dir(90)), C = IP((0,0), 0, 140);
pair I = incenter(BA+BC+CA),
D = (I + reflect(B,C)*(I)),
E = (I + reflect(C,A)*(I)),
F = (I + reflect(A,B)*(I));
draw(A--B--C--cycle);
draw Incircle(A,B,C);
draw(B--I--C);
label("$A$",A,dir(A));
label("$B$",B,dir(B));
label("$C$",C,dir(C));
dot("$I$", I, 2*dir(-45));
dot("$D$", D, 0.5*dir(D));
dot("$E$", E, dir(E));
dot("$F$", F, 0.5*dir(F));
</ think> Now, we can see that $\angle BIC = 90^{\circ} + \frac{\angle BAC}{2}$, so $BI = \frac{BC}{2}\frac{1}{\sin(\angle BIC)} =  \frac{BC}{2}\frac{1}{\sin(\frac{\angle BAC}{2})}$. By the Extended Law of Sines (proof here or just look it up online), $BC = 2R\sin\angle BAC$, so
\begin{align*}
BI &= \frac{BC}{2}\frac{1}{\sin(\frac{\angle BAC}{2})} \\
&= \frac{2R\sin\angle BAC}{2}\frac{1}{\sin(\frac{\angle BAC}{2})} \\
&= R\frac{\sin\angle BAC}{\sin(\frac{\angle BAC}{2})}.
\end{align*}We now take the angle bisector of $\angle BAC$ and let it intersect $BC$ at $X$. We have that $AX$ is a median of $\triangle ABC$, so by Apollonius's Theorem, $AX = \frac{\sqrt{2AB^2 + 2AC^2 - BC^2}}{2} = \frac{\sqrt{2(13^2) + 2(15^2) - (14^2)}}{2} = \frac{\sqrt{522}}{2}$. Let $\angle BAC = 2\alpha$. By the Law of Sines, $\frac{AX}{\sin\alpha} = \frac{BC}{\sin2\alpha}$, so
\begin{align*}
\frac{\sqrt{522}}{2\sin\alpha} &= \frac{14}{\sin2\alpha} \\
\sin2\alpha &= \frac{14\cdot2\sin\alpha}{\sqrt{522}} \\
\sin2\alpha &= \frac{14\cdot2\sin\alpha}{\sqrt{522}} \\
2\sin\alpha\cos\alpha &= \frac{14\cdot2\sin\alpha}{\sqrt{522}} \\
\cos\alpha &= \frac{14}{\sqrt{522}} \\
\cos\alpha &= \frac{7}{\sqrt{261}} \\
\cos^2\alpha &= \frac{49}{261}.
\end{align*}By the Pythagorean Identity, $\sin^2\alpha = 1 - \cos^2\alpha = 1 - \frac{49}{261} = \frac{212}{261}$, so $\sin\alpha = \frac{2\sqrt{53}}{\sqrt{261}}$. The Double Angle formula then gives $\sin 2\alpha = 2\sin\alpha\cos\alpha = \frac{14\sqrt{53}}{\sqrt{261}}$, and
\begin{align*}
BI &= R\frac{\sin\angle BAC}{\sin(\frac{\angle BAC}{2})} \\
&= 2R\sin\alpha \\
&= \frac{14\sqrt{53}}{\sqrt{261}}\cdot\frac{\sqrt{261}}{7} \\
&= \boxed{2\sqrt{53}}.
